}
for name,(x1,y1,x2,y2,g,scale) in regions.items():
    c = img.crop((x1,y1,x2,y2))
    c = c.resize((int(c.width*scale), int(c.height*scale)), Image.LANCZOS)
    c = gamma(c, g)
    c.save(f'/tmp/pano/{name}.png')
print('done')
